import { useMemo, useState } from 'react';
import { useLocation } from 'wouter';
import {
  CalendarDays, ChevronLeft, ChevronRight, FileText, Plus, Repeat2, BarChart3,
  Settings, Target, TrendingDown, TrendingUp, Users, Wallet, X, Pencil, Trash2,
  Archive, History, SlidersHorizontal, CheckCircle2, AlertTriangle, CircleDollarSign,
  Pause, Play, SkipForward, Ban, MoreHorizontal, CalendarClock, Check, ListChecks, Eye,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import { useLanguage } from '@/contexts/LanguageContext';
import AppSectionHeader from '@/components/AppSectionHeader';
import { useDeleteConfirmation } from '@/contexts/DeleteConfirmationContext';
import type {
  Budget, BudgetProfile, ExpenseCategoryDefinition, ExpenseTransaction, Frequency,
  Goal, GoalContribution, IncomeCategory, IncomeSource, IncomeTransaction, PaymentMethod, RecurringExpenseRule,
  SkipRange, PauseWindow, RecurringFrequency, ExpenseType,
} from '../personalBudget/types';
import { DEFAULT_EXPENSE_CATEGORIES, getPersonalBudgetProfile, materializeRecurringProfile, savePersonalBudgetProfile } from '../personalBudget/storage';
import { monthKey, monthLabel, shiftMonth } from '../personalBudget/foundation';
import ReportsAnalyticsView from '@/components/ReportsAnalyticsView';
import { expectedIncomeForMonth, receivedIncomeForMonth, actualExpensesForMonth, stepFiveBudgetSummary, stepFiveGuidance, goalProgress, goalRequiredMonthlyAllocation } from '../personalBudget/calculations';
import { calculateMonthlyCommitment, calculateNextOccurrenceDate } from '../personalBudget/recurrenceEngine';

const tabs = [
  { id: 'overview', key: 'personalBudgetOverview', icon: Wallet },
  { id: 'income', key: 'personalBudgetIncome', icon: TrendingUp },
  { id: 'expenses', key: 'personalBudgetExpenses', icon: TrendingDown },
  { id: 'recurring', key: 'personalBudgetRecurring', icon: Repeat2 },
  { id: 'reports', key: 'personalBudgetReports', icon: BarChart3 },
] as const;
type TabId = 'overview' | 'income' | 'expenses' | 'recurring' | 'family' | 'goals' | 'calendar' | 'reports' | 'settings';

type IncomeForm = {
  name: string; category: IncomeCategory; amount: string; amountType: 'Fixed' | 'Variable'; frequency: Frequency;
  expectedDate: string; startDate: string; endDate: string; personId: string; includeInBudget: boolean;
};
type TransactionForm = { title: string; amount: string; date: string; status: 'Expected' | 'Received' | 'Partial'; sourceId: string };
type ExpenseForm = { title: string; amount: string; category: string; subcategory: string; date: string; personId: string; paymentMethod: PaymentMethod; note: string; status: 'Planned' | 'Paid' | 'Skipped' | 'Cancelled'; includeInBudget: boolean; recurringRuleId?: string; expenseType: ExpenseType; weekLabel: string };
type RecurringForm = { title: string; amount: string; category: string; subcategory: string; frequency: RecurringFrequency; startDate: string; endDate: string; amountType: 'Fixed' | 'Variable'; paymentMethod: PaymentMethod; personId: string; includeInBudget: boolean; intervalCount: string; customUnit: 'days' | 'weeks' | 'months' | 'years'; dayOfMonth: string; dayOfWeek: string; monthOfYear: string; notes: string; active: boolean };
type GoalForm = { title: string; targetAmount: string; currentAmount: string; targetDate: string; category: string; monthlyAllocation: string; priority: 'Low' | 'Medium' | 'High'; active: boolean; notes: string };

const incomeCategories: IncomeCategory[] = ['Salary', 'Business', 'Rental', 'Freelance', 'Commission', 'Interest', 'Dividend', 'Investment', 'Pension', 'Bonus', 'Other'];
const frequencies: Frequency[] = ['Monthly', 'Weekly', 'Daily', 'Quarterly', 'Yearly', 'Custom', 'One-time', 'Irregular'];
const recurringFrequencies: RecurringFrequency[] = ['Daily', 'Weekly', 'Monthly', 'Quarterly', 'Yearly', 'Custom'];
const paymentMethods: PaymentMethod[] = ['Cash', 'UPI', 'Bank', 'Credit Card', 'Debit Card', 'Wallet', 'Other'];

const emptyIncomeForm = (): IncomeForm => ({ name: '', category: 'Salary', amount: '', amountType: 'Fixed', frequency: 'Monthly', expectedDate: '', startDate: '', endDate: '', personId: 'Self', includeInBudget: true });
const emptyTransactionForm = (): TransactionForm => ({ title: '', amount: '', date: new Date().toISOString().slice(0, 10), status: 'Received', sourceId: '' });
const emptyExpenseForm = (): ExpenseForm => ({ title: '', amount: '', category: 'Food', subcategory: 'Groceries', date: new Date().toISOString().slice(0, 10), personId: 'Self', paymentMethod: 'UPI', note: '', status: 'Paid', includeInBudget: true, expenseType: 'Daily', weekLabel: '' });
const emptyGoalForm = (): GoalForm => ({ title: '', targetAmount: '', currentAmount: '0', targetDate: '', category: 'Emergency Fund', monthlyAllocation: '', priority: 'Medium', active: true, notes: '' });
const emptyRecurringForm = (): RecurringForm => ({ title: '', amount: '', category: 'Food', subcategory: 'Groceries', frequency: 'Monthly', startDate: new Date().toISOString().slice(0, 10), endDate: '', amountType: 'Fixed', paymentMethod: 'UPI', personId: 'Self', includeInBudget: true, intervalCount: '1', customUnit: 'days', dayOfMonth: '', dayOfWeek: '', monthOfYear: '', notes: '', active: true });

function money(amount: number): string { return `₹${Math.round(amount).toLocaleString('en-IN')}`; }
function positiveAmount(value: string): number { return Number(value); }
function isInMonth(date: string, month: string): boolean { return Boolean(date?.startsWith(month)); }
function today(): string { return new Date().toISOString().slice(0, 10); }
function formatDatePlusDays(dateStr: string, days: number): string { const date = new Date(`${dateStr}T12:00:00`); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10); }

export default function PersonalBudget() {
  const [, navigate] = useLocation();
  const { t, language } = useLanguage();
  const { requestDelete } = useDeleteConfirmation();
  const [profile, setProfile] = useState<BudgetProfile>(() => getPersonalBudgetProfile());
  const [activeTab, setActiveTab] = useState<TabId>('overview');
  const [selectedMonth, setSelectedMonth] = useState(profile.selectedMonth || monthKey(new Date()));
  const [incomeModal, setIncomeModal] = useState(false);
  const [editingIncomeId, setEditingIncomeId] = useState<string | null>(null);
  const [transactionModal, setTransactionModal] = useState(false);
  const [expenseModal, setExpenseModal] = useState(false);
  const [expenseEntryMode, setExpenseEntryMode] = useState<ExpenseType>('Daily');
  const [recurringModal, setRecurringModal] = useState(false);
  const [goalModal, setGoalModal] = useState(false);
  const [categoryModal, setCategoryModal] = useState(false);
  const [incomeForm, setIncomeForm] = useState<IncomeForm>(emptyIncomeForm);
  const [transactionForm, setTransactionForm] = useState<TransactionForm>(emptyTransactionForm);
  const [expenseForm, setExpenseForm] = useState<ExpenseForm>(emptyExpenseForm);
  const [recurringForm, setRecurringForm] = useState<RecurringForm>(emptyRecurringForm);
  const [goalForm, setGoalForm] = useState<GoalForm>(emptyGoalForm);
  const [editingGoalId, setEditingGoalId] = useState<string | null>(null);
  const [editingRecurringId, setEditingRecurringId] = useState<string | null>(null);
  const [editingExpenseId, setEditingExpenseId] = useState<string | null>(null);
  const [incomeError, setIncomeError] = useState('');
  const [transactionError, setTransactionError] = useState('');
  const [expenseError, setExpenseError] = useState('');
  const [recurringError, setRecurringError] = useState('');
  const [goalError, setGoalError] = useState('');
  const [success, setSuccess] = useState('');
  const [expenseFilter, setExpenseFilter] = useState<'month' | 'last' | 'custom'>('month');
  const [customFrom, setCustomFrom] = useState(`${selectedMonth}-01`);
  const [customTo, setCustomTo] = useState(today());
  const [historySource, setHistorySource] = useState<IncomeSource | null>(null);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryIcon, setNewCategoryIcon] = useState('');
  const [categoryError, setCategoryError] = useState('');

  const updateProfile = (updater: (current: BudgetProfile) => BudgetProfile) => {
    setProfile(current => { const next = updater(current); savePersonalBudgetProfile(next); return next; });
  };
  const locale = language === 'en' ? 'en-IN' : language;
  const members = profile.householdMembers.length ? profile.householdMembers : [{ id: 'self', name: 'Self', relationship: 'Self' as const }];
  const currentMonthTransactions = useMemo(() => profile.incomeTransactions.filter(item => isInMonth(item.date, selectedMonth)), [profile.incomeTransactions, selectedMonth]);
  const currentMonthExpenses = useMemo(() => profile.expenseTransactions.filter(item => isInMonth(item.date, selectedMonth)), [profile.expenseTransactions, selectedMonth]);
  const recurringOccurrences = useMemo(() => currentMonthExpenses.filter(item => item.recurringRuleId), [currentMonthExpenses]);
  const recurringCommitment = useMemo(() => calculateMonthlyCommitment(profile.recurringExpenseRules, selectedMonth), [profile.recurringExpenseRules, selectedMonth]);
  const recurringPaid = useMemo(() => recurringOccurrences.filter(item => item.status === 'Paid' && item.includeInBudget !== false).reduce((sum, item) => sum + item.amount, 0), [recurringOccurrences]);
  const recurringPending = useMemo(() => recurringOccurrences.filter(item => item.status === 'Planned' && item.includeInBudget !== false).reduce((sum, item) => sum + item.amount, 0), [recurringOccurrences]);
  const recurringSkipped = useMemo(() => recurringOccurrences.filter(item => item.status === 'Skipped').reduce((sum, item) => sum + item.amount, 0), [recurringOccurrences]);
  const expectedIncome = useMemo(() => expectedIncomeForMonth(profile.incomeSources, selectedMonth), [profile.incomeSources, selectedMonth]);
  const receivedIncome = useMemo(() => receivedIncomeForMonth(profile.incomeTransactions, selectedMonth), [profile.incomeTransactions, selectedMonth]);
  const actualExpenses = useMemo(() => actualExpensesForMonth(profile.expenseTransactions, selectedMonth), [profile.expenseTransactions, selectedMonth]);
  const stepFiveSummary = useMemo(() => stepFiveBudgetSummary(profile, selectedMonth), [profile, selectedMonth]);
  const guidance = useMemo(() => stepFiveGuidance(profile, selectedMonth, stepFiveSummary), [profile, selectedMonth, stepFiveSummary]);
  const plannedExpenses = useMemo(() => stepFiveSummary.committed + stepFiveSummary.variableBudget + stepFiveSummary.goalCommitments, [stepFiveSummary]);
  const remaining = stepFiveSummary.remainingAvailableCash;
  const budgetUsed = expectedIncome > 0 ? Math.round((stepFiveSummary.actualSpending / expectedIncome) * 100) : 0;
  const upcomingOccurrences = useMemo(() => profile.expenseTransactions.filter(item => item.recurringRuleId && item.date > today() && item.date <= formatDatePlusDays(today(), 7) && item.status === 'Planned').sort((a, b) => a.date.localeCompare(b.date)), [profile.expenseTransactions]);

  const filteredExpenses = useMemo(() => {
    if (expenseFilter === 'month') return currentMonthExpenses;
    if (expenseFilter === 'last') {
      const last = shiftMonth(selectedMonth, -1);
      return profile.expenseTransactions.filter(item => isInMonth(item.date, last));
    }
    return profile.expenseTransactions.filter(item => item.date >= customFrom && item.date <= customTo);
  }, [customFrom, customTo, currentMonthExpenses, expenseFilter, profile.expenseTransactions, selectedMonth]);

  const topCategories = useMemo(() => {
    const totals = new Map<string, number>();
    currentMonthExpenses.filter(item => item.status === 'Paid' && item.includeInBudget !== false).forEach(item => totals.set(item.category, (totals.get(item.category) ?? 0) + item.amount));
    return Array.from(totals.entries()).sort((a, b) => b[1] - a[1]).slice(0, 5);
  }, [currentMonthExpenses]);

  const changeMonth = (offset: number) => {
    const next = shiftMonth(selectedMonth, offset);
    setSelectedMonth(next);
    updateProfile(profile => materializeRecurringProfile({ ...profile, selectedMonth: next }, next));
  };
  const flash = (message: string) => { setSuccess(message); window.setTimeout(() => setSuccess(''), 1800); };

  const openIncomeEditor = (source: IncomeSource) => { setEditingIncomeId(source.id); setIncomeForm({ name: source.name, category: source.category as IncomeCategory, amount: String(source.amount), amountType: source.amountType, frequency: source.frequency, expectedDate: source.expectedDate ?? '', startDate: source.startDate ?? '', endDate: source.endDate ?? '', personId: source.personId ?? 'Self', includeInBudget: source.includeInBudget !== false }); setIncomeError(''); setIncomeModal(true); };
  const openAddExpense = (mode: ExpenseType = 'Daily', category?: string) => { setEditingExpenseId(null); setExpenseEntryMode(mode); const base = emptyExpenseForm(); const categoryName = category === 'Milk' ? 'Food' : category ?? base.category; const subcategory = category === 'Milk' ? 'Milk' : category ? (profile.expenseCategories.find(item => item.name === category)?.subcategories?.[0] ?? '') : base.subcategory; setExpenseForm({ ...base, expenseType: mode, category: categoryName, subcategory, title: category === 'Milk' ? 'Milk' : category === 'Food' ? 'Food' : category === 'Transport' ? 'Transport' : '' }); setExpenseError(''); setExpenseModal(true); };
  const openRecurringEditor = (rule: RecurringExpenseRule) => { setEditingRecurringId(rule.id); setRecurringForm({ title: rule.title, amount: String(rule.amount), category: rule.category, subcategory: rule.subcategory ?? '', frequency: rule.frequency, startDate: rule.startDate, endDate: rule.endDate ?? '', amountType: rule.amountType, paymentMethod: rule.paymentMethod ?? 'UPI', personId: rule.personId ?? 'Self', includeInBudget: rule.includeInBudget !== false, intervalCount: String(rule.intervalCount ?? 1), customUnit: rule.customUnit ?? 'days', dayOfMonth: rule.dayOfMonth ? String(rule.dayOfMonth) : '', dayOfWeek: rule.dayOfWeek !== undefined ? String(rule.dayOfWeek) : '', monthOfYear: rule.monthOfYear ? String(rule.monthOfYear) : '', notes: rule.notes ?? '', active: rule.status === 'Active' }); setRecurringError(''); setRecurringModal(true); };
  const openAddRecurring = () => { setEditingRecurringId(null); setRecurringForm(emptyRecurringForm()); setRecurringError(''); setRecurringModal(true); };
  const openEditExpense = (expense: ExpenseTransaction) => { setEditingExpenseId(expense.id); setExpenseForm({ title: expense.title, amount: String(expense.amount), category: expense.category, subcategory: expense.subcategory ?? '', date: expense.date, personId: expense.personId ?? 'self', paymentMethod: expense.paymentMethod ?? 'Other', note: expense.notes ?? '', status: expense.status === 'Paid' ? 'Paid' : expense.status === 'Skipped' ? 'Skipped' : expense.status === 'Cancelled' ? 'Cancelled' : 'Planned', includeInBudget: expense.includeInBudget !== false, recurringRuleId: expense.recurringRuleId, expenseType: expense.expenseType ?? (expense.recurringRuleId ? 'Recurring' : 'Daily'), weekLabel: expense.weekLabel ?? '' }); setExpenseError(''); setExpenseModal(true); };

  const saveIncomeSource = () => {
    const amount = positiveAmount(incomeForm.amount);
    if (!incomeForm.name.trim() || !Number.isFinite(amount) || amount < 0 || (incomeForm.amountType === 'Fixed' && amount <= 0)) { setIncomeError(t('pbIncomeRequired' as any)); return; }
    const source: IncomeSource = { id: editingIncomeId ?? `income_${Date.now()}`, name: incomeForm.name.trim(), category: incomeForm.category, amount, amountType: incomeForm.amountType, frequency: incomeForm.frequency, expectedDate: incomeForm.expectedDate || undefined, startDate: incomeForm.startDate || undefined, endDate: incomeForm.endDate || undefined, personId: incomeForm.personId, status: 'Active', includeInBudget: incomeForm.includeInBudget };
    updateProfile(profile => ({ ...profile, incomeSources: editingIncomeId ? profile.incomeSources.map(item => item.id === editingIncomeId ? { ...item, ...source } : item) : [...profile.incomeSources, source] }));
    setIncomeModal(false); setEditingIncomeId(null); setIncomeForm(emptyIncomeForm()); setIncomeError(''); flash(t('personalBudgetSuccessIncome')); setActiveTab('income');
  };

  const saveRecurringRule = () => {
    const amount = positiveAmount(recurringForm.amount);
    const intervalCount = Math.max(1, Number(recurringForm.intervalCount || 1));
    if (!recurringForm.title.trim() || !Number.isFinite(amount) || amount <= 0 || !recurringForm.startDate) { setRecurringError(t('pbRecurringRequired' as any)); return; }
    const existing = editingRecurringId ? profile.recurringExpenseRules.find(item => item.id === editingRecurringId) : undefined;
    const rule: RecurringExpenseRule = { id: editingRecurringId ?? `recurring_${Date.now()}`, title: recurringForm.title.trim(), amount, category: recurringForm.category, subcategory: recurringForm.subcategory || undefined, frequency: recurringForm.frequency, intervalCount, customUnit: recurringForm.customUnit, dayOfMonth: recurringForm.dayOfMonth ? Math.min(31, Math.max(1, Number(recurringForm.dayOfMonth))) : undefined, dayOfWeek: recurringForm.dayOfWeek ? Number(recurringForm.dayOfWeek) : undefined, monthOfYear: recurringForm.monthOfYear ? Math.min(12, Math.max(1, Number(recurringForm.monthOfYear))) : undefined, startDate: recurringForm.startDate, endDate: recurringForm.endDate || undefined, amountType: recurringForm.amountType, status: recurringForm.active ? (existing?.status === 'Paused' ? 'Active' : 'Active') : 'Paused', paymentMethod: recurringForm.paymentMethod, personId: recurringForm.personId, includeInBudget: recurringForm.includeInBudget, notes: recurringForm.notes.trim() || undefined, skipRanges: existing?.skipRanges ?? [], pauseWindows: existing?.pauseWindows ?? [] };
    updateProfile(profile => { const recurringExpenseRules = editingRecurringId ? profile.recurringExpenseRules.map(item => item.id === editingRecurringId ? rule : item) : [...profile.recurringExpenseRules, rule]; const expenseTransactions = editingRecurringId ? profile.expenseTransactions.map(item => item.recurringRuleId === editingRecurringId && item.status === 'Planned' && item.date >= today() && (item.amountOverride === undefined || item.amountOverride === existing?.amount) ? { ...item, title: rule.title, category: rule.category, subcategory: rule.subcategory, amount: rule.amount, amountOverride: rule.amount, paymentMethod: rule.paymentMethod, includeInBudget: rule.includeInBudget } : item) : profile.expenseTransactions; return materializeRecurringProfile({ ...profile, recurringExpenseRules, expenseTransactions }, selectedMonth); });
    setRecurringModal(false); setEditingRecurringId(null); setRecurringForm(emptyRecurringForm()); setRecurringError(''); flash(t('personalBudgetRecurringSaved')); setActiveTab('recurring');
  };
  const toggleRecurringRule = (id: string) => updateProfile(profile => ({ ...profile, recurringExpenseRules: profile.recurringExpenseRules.map(rule => rule.id === id ? { ...rule, status: rule.status === 'Active' ? 'Paused' : 'Active' } : rule) }));
  const archiveRecurringRule = (id: string) => { if (!window.confirm(t('personalBudgetArchiveConfirm'))) return; updateProfile(profile => ({ ...profile, recurringExpenseRules: profile.recurringExpenseRules.map(rule => rule.id === id ? { ...rule, status: 'Archived' } : rule) })); };
  const deleteFutureRecurringRule = (id: string) => { const rule = profile.recurringExpenseRules.find(item => item.id === id); requestDelete({ title: `${t('pbDelete' as any)} ${t('personalBudgetRecurring' as any)}${rule?.title ? ` — ${rule.title}` : ''}`, message: t('auditActionCannotUndo' as any), onConfirm: () => updateProfile(profile => ({ ...profile, recurringExpenseRules: profile.recurringExpenseRules.map(rule => rule.id === id ? { ...rule, status: 'Deleted' } : rule), expenseTransactions: profile.expenseTransactions.filter(item => item.recurringRuleId !== id || item.status === 'Paid') })) }); };
  const addSkipRange = (id: string, startDate: string, endDate: string) => updateProfile(profile => ({ ...profile, recurringExpenseRules: profile.recurringExpenseRules.map(rule => rule.id === id ? { ...rule, skipRanges: [...(rule.skipRanges ?? []), { id: `skip_${Date.now()}`, startDate, endDate }] } : rule), expenseTransactions: profile.expenseTransactions.map(item => item.recurringRuleId === id && item.date >= startDate && item.date <= endDate && item.status !== 'Paid' ? { ...item, status: 'Skipped' } : item) }));
  const promptSkipRange = (id: string) => { const startDate = window.prompt(t('personalBudgetSkipFrom'), today()); if (!startDate) return; const endDate = window.prompt(t('personalBudgetSkipTo'), startDate); if (!endDate || endDate < startDate) return; addSkipRange(id, startDate, endDate); };
  const pauseRecurringRule = (id: string) => { const startDate = window.prompt(t('personalBudgetPauseFrom'), today()); if (!startDate) return; const endDate = window.prompt(t('personalBudgetPauseTo'), startDate); if (!endDate || endDate < startDate) return; updateProfile(profile => ({ ...profile, recurringExpenseRules: profile.recurringExpenseRules.map(rule => rule.id === id ? { ...rule, status: 'Paused', pauseWindows: [...(rule.pauseWindows ?? []), { id: `pause_${Date.now()}`, startDate, endDate }] } : rule) })); };
  const updateRecurringOccurrenceStatus = (id: string, status: ExpenseTransaction['status']) => updateProfile(profile => ({ ...profile, expenseTransactions: profile.expenseTransactions.map(item => item.id === id ? { ...item, status } : item) }));
  const markRecurringOccurrencePaid = (id: string) => { const current = profile.expenseTransactions.find(item => item.id === id); if (!current) return; const rawActual = window.prompt(t('personalBudgetActualAmountPrompt'), String(current.amount)); if (rawActual === null) return; const actual = Number(rawActual); if (!Number.isFinite(actual) || actual <= 0) return; updateProfile(profile => ({ ...profile, expenseTransactions: profile.expenseTransactions.map(item => item.id === id ? { ...item, amount: actual, amountOverride: actual, status: 'Paid', actualTransactionId: item.id } : item) })); };
  const markTodayPaid = () => { const count = currentMonthExpenses.filter(item => item.recurringRuleId && item.date === today() && item.status === 'Planned').length; if (!count || !window.confirm(`${t('personalBudgetBulkPaidConfirm')} ${count}?`)) return; updateProfile(profile => ({ ...profile, expenseTransactions: profile.expenseTransactions.map(item => item.recurringRuleId && item.date === today() && item.status === 'Planned' ? { ...item, status: 'Paid', actualTransactionId: item.id, amountOverride: item.amount } : item) })); };

  const saveIncomeTransaction = () => {
    const amount = positiveAmount(transactionForm.amount);
    if (!transactionForm.title.trim() || !Number.isFinite(amount) || amount <= 0 || !transactionForm.date) { setTransactionError(t('pbTransactionRequired' as any)); return; }
    const transaction: IncomeTransaction = { id: `income_tx_${Date.now()}`, sourceId: transactionForm.sourceId || undefined, title: transactionForm.title.trim(), amount, date: transactionForm.date, status: transactionForm.status };
    updateProfile(profile => ({ ...profile, incomeTransactions: [...profile.incomeTransactions, transaction] }));
    setTransactionModal(false); setTransactionForm(emptyTransactionForm()); setTransactionError(''); flash(t('personalBudgetSuccessIncome')); setActiveTab('income');
  };

  const saveExpense = () => {
    const amount = positiveAmount(expenseForm.amount);
    if (!Number.isFinite(amount) || amount <= 0 || !expenseForm.category || !expenseForm.date) { setExpenseError(t('pbExpenseRequired' as any)); return; }
    const currentExpense = editingExpenseId ? profile.expenseTransactions.find(item => item.id === editingExpenseId) : undefined;
    const next: ExpenseTransaction = { id: editingExpenseId ?? `expense_${Date.now()}`, title: expenseForm.title.trim() || expenseForm.subcategory || expenseForm.category, amount, category: expenseForm.category, subcategory: expenseForm.subcategory || undefined, date: expenseForm.date, status: expenseForm.status, paymentMethod: expenseForm.paymentMethod, personId: expenseForm.personId, notes: expenseForm.note.trim() || undefined, includeInBudget: expenseForm.includeInBudget, recurringRuleId: expenseForm.recurringRuleId, isOccurrence: currentExpense?.isOccurrence ?? Boolean(expenseForm.recurringRuleId), amountOverride: expenseForm.recurringRuleId ? amount : undefined, actualTransactionId: currentExpense?.actualTransactionId, expenseType: expenseForm.recurringRuleId ? 'Recurring' : expenseForm.expenseType, weekLabel: expenseForm.expenseType === 'Weekly' ? (expenseForm.weekLabel || expenseForm.date) : undefined };
    updateProfile(profile => ({ ...profile, expenseTransactions: editingExpenseId ? profile.expenseTransactions.map(item => item.id === editingExpenseId ? next : item) : [...profile.expenseTransactions, next] }));
    setExpenseModal(false); setExpenseError(''); setEditingExpenseId(null); setExpenseForm(emptyExpenseForm()); flash(t('personalBudgetSuccessExpense')); setActiveTab('expenses');
  };

  const saveGoal = () => {
    const targetAmount = Number(goalForm.targetAmount);
    const currentAmount = Number(goalForm.currentAmount || 0);
    if (!goalForm.title.trim() || !Number.isFinite(targetAmount) || targetAmount <= 0 || !Number.isFinite(currentAmount) || currentAmount < 0 || currentAmount > targetAmount) { setGoalError(t('pbGoalRequired' as any)); return; }
    const goal: Goal = { id: editingGoalId ?? `goal_${Date.now()}`, title: goalForm.title.trim(), targetAmount, currentAmount, targetDate: goalForm.targetDate || undefined, category: goalForm.category, status: goalForm.active ? 'Active' : 'Paused', monthlyAllocation: goalForm.monthlyAllocation ? Number(goalForm.monthlyAllocation) : undefined, priority: goalForm.priority, active: goalForm.active, notes: goalForm.notes.trim() || undefined };
    updateProfile(current => ({ ...current, goals: editingGoalId ? current.goals.map(item => item.id === editingGoalId ? goal : item) : [...current.goals, goal] }));
    setGoalModal(false); setEditingGoalId(null); setGoalForm(emptyGoalForm()); setGoalError(''); flash(t('pbGoalSaved' as any)); setActiveTab('overview');
  };
  const openGoalEditor = (goal: Goal) => { setEditingGoalId(goal.id); setGoalForm({ title: goal.title, targetAmount: String(goal.targetAmount), currentAmount: String(goal.currentAmount), targetDate: goal.targetDate ?? '', category: goal.category, monthlyAllocation: goal.monthlyAllocation ? String(goal.monthlyAllocation) : '', priority: goal.priority ?? 'Medium', active: goal.active !== false && goal.status === 'Active', notes: goal.notes ?? '' }); setGoalError(''); setGoalModal(true); };
  const addGoalContribution = (goal: Goal) => { const raw = window.prompt(t('pbContributionPrompt' as any), '5000'); if (raw === null) return; const amount = Number(raw); if (!Number.isFinite(amount) || amount <= 0) return; const contribution: GoalContribution = { id: `goal_contribution_${Date.now()}`, goalId: goal.id, amount, date: today() }; updateProfile(current => ({ ...current, goals: current.goals.map(item => item.id === goal.id ? { ...item, currentAmount: item.currentAmount + amount } : item), goalContributions: [...current.goalContributions, contribution] })); flash(t('pbGoalContributionSaved' as any)); };

  const deleteGoal = (goalId: string) => {
    const goal = profile.goals.find(item => item.id === goalId);
    requestDelete({
      title: `${t('pbDelete' as any)} ${t('personalBudgetGoalsTitle' as any)}${goal?.title ? ` — ${goal.title}` : ''}`,
      message: t('auditActionCannotUndo' as any),
      onConfirm: () => {
        updateProfile(current => ({
          ...current,
          goals: current.goals.filter(item => item.id !== goalId),
          goalContributions: current.goalContributions.filter(item => item.goalId !== goalId),
        }));
        flash(t('pbGoalDeleted' as any));
      },
    });
  };

  const deleteExpense = (id: string) => { const expense = profile.expenseTransactions.find(item => item.id === id); requestDelete({ title: `${t('pbDelete' as any)} ${t('personalBudgetExpenses' as any)}${expense?.title ? ` — ${expense.title}` : ''}`, message: t('auditActionCannotUndo' as any), onConfirm: () => updateProfile(profile => ({ ...profile, expenseTransactions: profile.expenseTransactions.filter(item => item.id !== id) })) }); };
  const archiveIncome = (id: string) => { if (!window.confirm(t('personalBudgetArchiveConfirm'))) return; updateProfile(profile => ({ ...profile, incomeSources: profile.incomeSources.map(item => item.id === id ? { ...item, status: 'Archived' } : item) })); };
  const deleteIncome = (id: string) => { const income = profile.incomeSources.find(item => item.id === id); requestDelete({ title: `${t('pbDelete' as any)} ${t('personalBudgetIncome' as any)}${income?.name ? ` — ${income.name}` : ''}`, message: t('auditActionCannotUndo' as any), onConfirm: () => updateProfile(profile => ({ ...profile, incomeSources: profile.incomeSources.filter(item => item.id !== id), incomeTransactions: profile.incomeTransactions.filter(item => item.sourceId !== id) })) }); };

  const addCustomCategory = () => {
    if (!newCategoryName.trim()) { setCategoryError(t('pbCategoryRequired' as any)); return; }
    const category: ExpenseCategoryDefinition = { id: `cat_${Date.now()}`, name: newCategoryName.trim(), subcategories: ['Other'], icon: newCategoryIcon || '📦', color: '#6b7280', isSystem: false };
    updateProfile(profile => ({ ...profile, expenseCategories: [...profile.expenseCategories, category] }));
    setNewCategoryName(''); setNewCategoryIcon(''); setCategoryError(''); setCategoryModal(false); flash(t('personalBudgetAddCustomCategory'));
  };

  const setCategoryBudget = (category: string, value: string) => {
    const amount = Number(value);
    if (!Number.isFinite(amount) || amount < 0) return;
    updateProfile(profile => {
      const existing = profile.budgets.find(item => item.month === selectedMonth && item.category === category);
      const budget: Budget = { id: existing?.id ?? `budget_${Date.now()}`, month: selectedMonth, category, plannedAmount: amount };
      return { ...profile, budgets: existing ? profile.budgets.map(item => item.id === existing.id ? budget : item) : [...profile.budgets, budget] };
    });
  };

  const selectTab = (tab: TabId) => setActiveTab(tab);
  const monthSelector = <div className="flex items-center justify-between gap-2 rounded-2xl border border-[#d1e5d7] bg-white p-2 shadow-sm"><Button aria-label={t('personalBudgetPreviousMonth')} variant="outline" size="sm" onClick={() => changeMonth(-1)} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-white px-3 font-black text-kharcha-navy shadow-sm hover:bg-[#f2fbf3]"><ChevronLeft size={17} className="mr-1" /><span className="hidden sm:inline">{t('personalBudgetPreviousMonth')}</span><span className="sm:hidden">{t('pbPreviousShort' as any)}</span></Button><div className="text-center"><p className="text-[10px] font-black uppercase tracking-[0.18em] text-gray-500">{t('personalBudgetOverview')}</p><p className="text-base font-black text-kharcha-navy">{monthLabel(selectedMonth, locale)}</p></div><Button aria-label={t('personalBudgetNextMonth')} variant="outline" size="sm" onClick={() => changeMonth(1)} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-white px-3 font-black text-kharcha-navy shadow-sm hover:bg-[#f2fbf3]"><span className="hidden sm:inline">{t('personalBudgetNextMonth')}</span><span className="sm:hidden">{t('pbNextShort' as any)}</span><ChevronRight size={17} className="ml-1" /></Button></div>;

  return <div className="min-h-screen bg-kharcha-cream pb-12">
    <AppSectionHeader
      title={t('personalBudget')}
      onBack={() => navigate('/')}
      backLabel={t('auditBackToKharcha' as any)}
    ><nav aria-label={t('personalBudget')} className="mx-auto mt-3 grid max-w-6xl grid-cols-2 gap-2 pb-1 sm:flex sm:overflow-x-auto">{tabs.map(tab => { const Icon = tab.icon; const active = tab.id === activeTab; return <button type="button" key={tab.id} aria-current={active ? 'page' : undefined} onClick={() => selectTab(tab.id)} className={`flex min-h-10 w-full items-center justify-center gap-1.5 rounded-xl border px-2 text-xs font-black transition-all active:scale-95 sm:min-h-11 sm:w-auto sm:shrink-0 sm:rounded-full sm:px-3.5 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#16834b] ${active ? 'border-[#16834b] bg-[#16834b] text-white shadow-sm' : 'border-[#d1e5d7] bg-white text-kharcha-navy hover:border-[#e87817] hover:bg-[#fffaf3]'}`}><Icon size={15} />{t(tab.key)}</button>; })}</nav>
    </AppSectionHeader>
    {success && <div role="status" className="fixed left-1/2 top-20 z-50 -translate-x-1/2 rounded-full border border-[#d1e5d7] bg-[#dff1e5] px-5 py-3 text-sm font-black text-[#16834b] shadow-sm"><CheckCircle2 size={16} className="mr-1 inline" />{success}</div>}
    <main className="mx-auto max-w-6xl space-y-5 px-4 py-5">
      {activeTab === 'overview' && <><OverviewScreen t={t} monthSelector={monthSelector} expectedIncome={expectedIncome} receivedIncome={receivedIncome} actualExpenses={actualExpenses} plannedExpenses={plannedExpenses} remaining={remaining} budgetUsed={budgetUsed} topCategories={topCategories} recurringCommitment={recurringCommitment.commitment} recurringPaid={recurringPaid} recurringPending={recurringPending} recurringSkipped={recurringSkipped} summary={stepFiveSummary} guidance={guidance} goals={profile.goals} onIncome={() => setActiveTab('income')} onExpense={() => openAddExpense('Daily')} onRecurring={() => { setActiveTab('expenses'); openAddRecurring(); }} onGoal={() => { setEditingGoalId(null); setGoalForm(emptyGoalForm()); setGoalModal(true); }} onEditGoal={openGoalEditor} onAddContribution={addGoalContribution} onDeleteGoal={deleteGoal} /><StepFivePanel t={t} summary={stepFiveSummary} guidance={guidance} goals={profile.goals} onGoal={() => { setEditingGoalId(null); setGoalForm(emptyGoalForm()); setGoalModal(true); }} onEditGoal={openGoalEditor} onAddContribution={addGoalContribution} onDeleteGoal={deleteGoal} /></>}
      {activeTab === 'income' && <IncomeScreen t={t} sources={profile.incomeSources} transactions={currentMonthTransactions} members={members} onAddSource={() => { setEditingIncomeId(null); setIncomeForm(emptyIncomeForm()); setIncomeModal(true); }} onAddTransaction={() => { setTransactionForm(emptyTransactionForm()); setTransactionModal(true); }} onEdit={openIncomeEditor} onArchive={archiveIncome} onDelete={deleteIncome} onHistory={setHistorySource} />}
      {activeTab === 'expenses' && <ExpenseScreen t={t} expenses={filteredExpenses} categories={profile.expenseCategories.length ? profile.expenseCategories : DEFAULT_EXPENSE_CATEGORIES} filter={expenseFilter} setFilter={setExpenseFilter} customFrom={customFrom} customTo={customTo} setCustomFrom={setCustomFrom} setCustomTo={setCustomTo} selectedMonth={selectedMonth} onAdd={() => openAddExpense('OneTime')} onAddDaily={(category?: string) => openAddExpense('Daily', category)} onAddWeekly={() => openAddExpense('Weekly')} onAddRecurring={openAddRecurring} onEdit={openEditExpense} onDelete={deleteExpense} onManageCategories={() => setCategoryModal(true)} budgets={profile.budgets.filter(item => item.month === selectedMonth)} actualExpenses={currentMonthExpenses} onSetBudget={setCategoryBudget} summary={stepFiveSummary} onGoal={() => { setEditingGoalId(null); setGoalForm(emptyGoalForm()); setGoalModal(true); }} />}
      {activeTab === 'recurring' && <RecurringScreen t={t} rules={profile.recurringExpenseRules} occurrences={recurringOccurrences} selectedMonth={selectedMonth} categories={profile.expenseCategories.length ? profile.expenseCategories : DEFAULT_EXPENSE_CATEGORIES} commitment={recurringCommitment} recurringPaid={recurringPaid} recurringPending={recurringPending} recurringSkipped={recurringSkipped} upcoming={upcomingOccurrences} onBack={() => setActiveTab('expenses')} onAdd={openAddRecurring} onEdit={openRecurringEditor} onToggle={toggleRecurringRule} onPause={pauseRecurringRule} onArchive={archiveRecurringRule} onDeleteFuture={deleteFutureRecurringRule} onSkipRange={promptSkipRange} onBulkPaid={markTodayPaid} onStatus={updateRecurringOccurrenceStatus} onMarkPaid={markRecurringOccurrencePaid} onEditOccurrence={openEditExpense} />}
      {activeTab === 'family' && <PlaceholderScreen t={t} title={t('personalBudgetFamily')} icon={Users} />}
      {activeTab === 'goals' && <PlaceholderScreen t={t} title={t('personalBudgetGoals')} icon={Target} />}
      {activeTab === 'calendar' && <CalendarScreen t={t} monthSelector={monthSelector} selectedMonth={selectedMonth} expenses={currentMonthExpenses} income={currentMonthTransactions} occurrences={recurringOccurrences} />}
      {activeTab === 'reports' && <ReportsAnalyticsView t={t} profile={profile} selectedMonth={selectedMonth} language={language} />}
      {activeTab === 'settings' && <PlaceholderScreen t={t} title={t('personalBudgetSettings')} icon={Settings} />}
    </main>
    {incomeModal && <IncomeSourceModal t={t} form={incomeForm} setForm={setIncomeForm} members={members} editing={Boolean(editingIncomeId)} error={incomeError} onClose={() => { setIncomeModal(false); setEditingIncomeId(null); }} onSave={saveIncomeSource} />}
    {transactionModal && <IncomeTransactionModal t={t} form={transactionForm} setForm={setTransactionForm} sources={profile.incomeSources} error={transactionError} onClose={() => setTransactionModal(false)} onSave={saveIncomeTransaction} />}
    {expenseModal && <ExpenseModal t={t} form={expenseForm} setForm={setExpenseForm} categories={profile.expenseCategories.length ? profile.expenseCategories : DEFAULT_EXPENSE_CATEGORIES} error={expenseError} editing={Boolean(editingExpenseId)} onClose={() => setExpenseModal(false)} onSave={saveExpense} />}
    {recurringModal && <RecurringModal t={t} form={recurringForm} setForm={setRecurringForm} categories={profile.expenseCategories.length ? profile.expenseCategories : DEFAULT_EXPENSE_CATEGORIES} members={members} error={recurringError} editing={Boolean(editingRecurringId)} onClose={() => { setRecurringModal(false); setEditingRecurringId(null); }} onSave={saveRecurringRule} />}
    {categoryModal && <CategoryModal t={t} name={newCategoryName} icon={newCategoryIcon} setName={setNewCategoryName} setIcon={setNewCategoryIcon} error={categoryError} categories={profile.expenseCategories} onClose={() => setCategoryModal(false)} onSave={addCustomCategory} />}
    {historySource && <HistoryModal t={t} source={historySource} transactions={profile.incomeTransactions.filter(item => item.sourceId === historySource.id)} onClose={() => setHistorySource(null)} />}
    {goalModal && <GoalModal t={t} form={goalForm} setForm={setGoalForm} editing={Boolean(editingGoalId)} error={goalError} onClose={() => { setGoalModal(false); setEditingGoalId(null); }} onSave={saveGoal} />}
  </div>;
}

function OverviewScreen({ t, monthSelector, expectedIncome, receivedIncome, actualExpenses, plannedExpenses, remaining, budgetUsed, topCategories, recurringCommitment, recurringPaid, recurringPending, recurringSkipped, onIncome, onExpense, onRecurring, onGoal }: any) {
  const metrics = [[t('personalBudgetExpectedIncome'), expectedIncome, 'text-[#16834b]'], [t('personalBudgetActualReceived'), receivedIncome, 'text-[#2563eb]'], [t('personalBudgetActualExpenses'), actualExpenses, 'text-[#c45a00]'], [t('personalBudgetRemaining'), remaining, remaining >= 0 ? 'text-[#16834b]' : 'text-red-600'], [t('personalBudgetPlannedExpenses'), plannedExpenses, 'text-kharcha-navy']];
  return <div className="space-y-5">{monthSelector}<section className="rounded-3xl border border-[#d1e5d7] bg-white p-5 shadow-md"><div className="flex items-start gap-3"><span className="grid h-12 w-12 shrink-0 place-items-center rounded-2xl border border-[#d1e5d7] bg-[#b9ddc9] text-[#16834b]"><CircleDollarSign size={25} /></span><div><h2 className="text-xl font-black text-kharcha-navy sm:text-2xl">{t('personalBudgetStartTitle')}</h2><p className="mt-1 text-sm text-gray-600">{t('personalBudgetStartDescription')}</p></div></div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><QuickAction label={t('personalBudgetAddIncome')} icon={TrendingUp} tone="green" onClick={onIncome} /><QuickAction label={t('personalBudgetAddExpense')} icon={TrendingDown} tone="orange" onClick={onExpense} /><QuickAction label={t('personalBudgetAddRecurring')} icon={Repeat2} tone="green" onClick={onRecurring} /><QuickAction label={t('personalBudgetAddGoal')} icon={Target} tone="orange" onClick={onGoal} /></div></section><section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{metrics.map(([label, value, color]: any[]) => <Card key={label} className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-wide text-gray-500">{label}</p><p className={`mt-1 text-xl font-black sm:text-2xl ${color}`}>{money(value)}</p></Card>)}<Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-wide text-gray-500">{t('personalBudgetUsed')}</p><p className="mt-1 text-xl font-black text-kharcha-navy sm:text-2xl">{budgetUsed}%</p></Card></section><section className="rounded-2xl border border-[#d1e5d7] bg-[#fffaf3] p-5 shadow-sm"><div className="flex items-center gap-2"><Repeat2 size={18} className="text-[#16834b]" /><h3 className="font-black text-kharcha-navy">{t('personalBudgetRecurring')}</h3></div><div className="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-4"><MetricPill label={t('personalBudgetMonthlyCommitment')} value={money(recurringCommitment)} tone="green" /><MetricPill label={t('personalBudgetRecurringPaid')} value={money(recurringPaid)} tone="blue" /><MetricPill label={t('personalBudgetRecurringPending')} value={money(recurringPending)} tone="orange" /><MetricPill label={t('personalBudgetRecurringSkipped')} value={money(recurringSkipped)} tone="gray" /></div></section><section className="grid gap-4 md:grid-cols-2"><Card className="rounded-2xl border border-[#d1e5d7] bg-white p-5 shadow-sm"><h3 className="flex items-center gap-2 font-black text-kharcha-navy"><TrendingDown size={18} className="text-[#e87817]" />{t('personalBudgetTopCategories')}</h3>{topCategories.length ? <div className="mt-3 space-y-2">{topCategories.map(([category, amount]: [string, number]) => <div key={category} className="flex justify-between border-b border-gray-100 pb-2 text-sm font-bold"><span>{pbOptionLabel(t, category)}</span><span className="text-[#c45a00]">{money(amount)}</span></div>)}</div> : <p className="mt-3 text-sm font-bold text-gray-500">{t('personalBudgetNoExpensesMonth')}</p>}</Card><Card className="rounded-2xl border border-[#d1e5d7] bg-white p-5 shadow-sm"><h3 className="font-black text-kharcha-navy">{t('personalBudgetExpected')} vs {t('personalBudgetReceived')}</h3><div className="mt-4 space-y-3"><ProgressRow label={t('personalBudgetExpected')} value={expectedIncome} max={Math.max(expectedIncome, 1)} color="bg-[#16834b]" /><ProgressRow label={t('personalBudgetReceived')} value={receivedIncome} max={Math.max(expectedIncome, 1)} color="bg-[#2563eb]" /></div></Card></section></div>;
  }

function QuickAction({ label, icon: Icon, tone, onClick }: { label: string; icon: typeof Plus; tone: 'green' | 'orange'; onClick: () => void }) { return <button type="button" onClick={onClick} className={`flex min-h-16 items-center justify-center gap-2 rounded-2xl border border-[#d1e5d7] px-2 text-center text-xs font-black text-black transition-transform active:scale-95 ${tone === 'green' ? 'bg-[#dff1e5] hover:bg-[#b9ddc9]' : 'bg-[#ffe8cf] hover:bg-[#ffd5ad]'}`}><Icon size={17} />{label}</button>; }
function MetricPill({ label, value, tone }: { label: string; value: string; tone: 'green' | 'blue' | 'orange' | 'gray' }) { const styles = { green: 'bg-[#dff1e5] text-[#16834b]', blue: 'bg-[#e4efff] text-[#2563eb]', orange: 'bg-[#fff3e3] text-[#c45a00]', gray: 'bg-gray-100 text-gray-700' }; return <div className={`rounded-xl border border-[#d1e5d7] p-3 ${styles[tone]}`}><p className="text-[10px] font-black uppercase leading-tight">{label}</p><p className="mt-1 text-lg font-black">{value}</p></div>; }
function ProgressRow({ label, value, max, color }: { label: string; value: number; max: number; color: string }) { return <div><div className="flex justify-between text-xs font-black"><span>{label}</span><span>{money(value)}</span></div><div className="mt-1 h-2 overflow-hidden rounded-full border border-[#d1e5d7] bg-gray-100"><div className={`h-full ${color}`} style={{ width: `${Math.min(100, value / max * 100)}%` }} /></div></div>; }

function IncomeScreen({ t, sources, transactions, members, onAddSource, onAddTransaction, onEdit, onArchive, onDelete, onHistory }: any) { return <section className="space-y-4"><div className="android-section-header flex flex-col gap-3 rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-xl font-black text-kharcha-navy">{t('personalBudgetIncome')}</h2><p className="text-xs font-bold text-gray-600">{t('personalBudgetIncomeSources')} · {t('personalBudgetActualReceived')}</p></div><div className="android-action-row flex flex-wrap gap-2"><Button onClick={onAddTransaction} variant="outline" className="min-h-11 flex-1 rounded-xl border border-[#d1e5d7] bg-white font-black text-black"><Plus size={15} className="mr-1" />{t('personalBudgetAddIncomeTransaction')}</Button><Button onClick={onAddSource} className="min-h-11 flex-1 rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white shadow-sm"><Plus size={15} className="mr-1" />{t('personalBudgetAddIncomeSource')}</Button></div></div>{sources.filter((source: IncomeSource) => source.status !== 'Archived').length === 0 ? <EmptyCard title={t('personalBudgetNoSources')} text={t('personalBudgetStartDescription')} action={t('personalBudgetAddIncomeSource')} onClick={onAddSource} /> : <div className="grid gap-3 md:grid-cols-2">{sources.filter((source: IncomeSource) => source.status !== 'Archived').map((source: IncomeSource) => <Card key={source.id} className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><span className="rounded-full border border-[#d1e5d7] bg-[#dff1e5] px-2 py-1 text-[10px] font-black uppercase text-[#16834b]">{pbOptionLabel(t, source.category)}</span><h3 className="mt-2 text-lg font-black text-kharcha-navy">{source.name}</h3><p className="text-xs font-bold text-gray-600">{source.amountType === 'Variable' ? t('personalBudgetVariable') : money(source.amount)} · {pbOptionLabel(t, source.frequency)}</p><p className="mt-1 text-xs font-bold text-gray-500">{source.includeInBudget === false ? t('pbNotIncludedBudget' as any) : t('personalBudgetIncludeInBudget')} · {pbOptionLabel(t, source.status)}</p></div><TrendingUp className="text-[#16834b]" size={22} /></div><div className="mt-4 flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => onEdit(source)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Pencil size={13} className="mr-1" />{t('personalBudgetEdit')}</Button><Button size="sm" variant="outline" onClick={() => onHistory(source)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><History size={13} className="mr-1" />{t('personalBudgetViewHistory')}</Button><Button size="sm" variant="outline" onClick={() => onArchive(source.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Archive size={13} className="mr-1" />{t('personalBudgetArchive')}</Button><Button size="sm" variant="outline" onClick={() => onDelete(source.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black text-red-600"><Trash2 size={13} /></Button></div></Card>)}</div>}<Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><h3 className="font-black text-kharcha-navy">{t('personalBudgetIncomeHistory')} ({transactions.length})</h3>{transactions.length ? <div className="mt-3 space-y-2">{transactions.map((item: IncomeTransaction) => <div key={item.id} className="flex items-center justify-between border-b border-gray-100 pb-2 text-sm"><div><p className="font-black">{item.title}</p><p className="text-xs text-gray-500">{item.date} · {pbOptionLabel(t, item.status)}</p></div><b className="text-[#16834b]">{money(item.amount)}</b></div>)}</div> : <p className="mt-2 text-sm font-bold text-gray-500">{t('personalBudgetHistoryEmpty')}</p>}</Card></section>; }

function ExpenseScreen({ t, expenses, categories, filter, setFilter, customFrom, customTo, setCustomFrom, setCustomTo, selectedMonth, onAdd, onAddDaily, onAddWeekly, onAddRecurring, onEdit, onDelete, onManageCategories, budgets, actualExpenses, onSetBudget, summary, onGoal }: any) { const total = expenses.filter((item: ExpenseTransaction) => item.status === 'Paid' && item.includeInBudget !== false).reduce((sum: number, item: ExpenseTransaction) => sum + item.amount, 0); return <section className="space-y-4"><div className="android-section-header flex flex-col gap-3 rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-xl font-black text-kharcha-navy">{t('personalBudgetExpenses')}</h2><p className="text-sm font-black text-[#c45a00]">{t('personalBudgetActualExpenses')}: {money(total)}</p></div><div className="android-action-row flex flex-wrap gap-2"><Button onClick={onAddDaily} className="min-h-11 rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white"><Plus size={15} className="mr-1" />{t('pbDaily' as any)}</Button><Button onClick={onAddWeekly} className="min-h-11 rounded-xl border border-[#d1e5d7] bg-[#2563eb] font-black text-white"><Plus size={15} className="mr-1" />{t('pbWeekly' as any)}</Button><Button onClick={onAdd} className="min-h-11 rounded-xl border border-[#d1e5d7] bg-[#e87817] font-black text-white"><Plus size={15} className="mr-1" />{t('pbOtherOneTime' as any)}</Button><Button onClick={onAddRecurring} variant="outline" className="min-h-11 rounded-xl border border-[#d1e5d7] bg-white font-black text-black"><Repeat2 size={15} className="mr-1" />{t('pbRecurring' as any)}</Button><Button onClick={onGoal} variant="outline" className="min-h-11 rounded-xl border border-[#d1e5d7] bg-white font-black text-black"><Target size={15} className="mr-1" />{t('pbGoalsTitle' as any)}</Button><Button onClick={onManageCategories} variant="outline" className="min-h-11 rounded-xl border border-[#d1e5d7] bg-white font-black text-black"><SlidersHorizontal size={15} className="mr-1" />{t('pbCategory' as any)}</Button></div></div><div className="rounded-2xl border border-[#d1e5d7] bg-[#f8fbf8] p-3"><p className="text-xs font-black uppercase tracking-wide text-gray-600">{t('pbDailyExpense' as any)}</p><div className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-4"><button type="button" onClick={() => onAddDaily('Milk')} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-white text-xs font-black text-black">{t('auditMilk' as any)}</button><button type="button" onClick={() => onAddDaily('Food')} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-white text-xs font-black text-black">{t('auditFood' as any)}</button><button type="button" onClick={() => onAddDaily('Transport')} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-white text-xs font-black text-black">{t('auditTransport' as any)}</button><button type="button" onClick={() => onAddDaily()} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-white text-xs font-black text-black">{t('pbOtherOneTime' as any)}</button></div></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><MetricPill label={t('pbCommitted' as any)} value={money(summary.committed)} tone="gray" /><MetricPill label={t('pbDaily' as any)} value={money(summary.dailyExpenses)} tone="green" /><MetricPill label={t('pbWeekly' as any)} value={money(summary.weeklyExpenses)} tone="blue" /><MetricPill label={t('pbRemainingCash' as any)} value={money(summary.remainingAvailableCash)} tone={summary.remainingAvailableCash < 0 ? 'orange' : 'green'} /></div><div className="flex gap-2 overflow-x-auto pb-1">{([['month', t('personalBudgetThisMonth')], ['last', t('personalBudgetLastMonth')], ['custom', t('personalBudgetCustomRange')]] as const).map(([key, label]) => <button key={key} onClick={() => setFilter(key)} className={`min-h-10 shrink-0 rounded-full border border-[#d1e5d7] px-4 text-xs font-black ${filter === key ? 'bg-[#16834b] text-white' : 'bg-white text-black'}`}>{label}</button>)}</div>{filter === 'custom' && <div className="grid gap-2 rounded-2xl border border-[#d1e5d7] bg-white p-3 sm:grid-cols-2"><label className="text-xs font-black">{t('personalBudgetFrom')}<Input type="date" value={customFrom} onChange={e => setCustomFrom(e.target.value)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></label><label className="text-xs font-black">{t('personalBudgetTo')}<Input type="date" value={customTo} onChange={e => setCustomTo(e.target.value)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></label></div>}{expenses.length === 0 ? <EmptyCard title={t('personalBudgetNoExpensesMonth')} text={t('personalBudgetAddFirstExpense')} action={t('personalBudgetAddExpense')} onClick={onAdd} /> : <div className="grid gap-3 md:grid-cols-2">{expenses.map((expense: ExpenseTransaction) => <Card key={expense.id} className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><span className="rounded-full border border-[#d1e5d7] bg-[#ffe8cf] px-2 py-1 text-[10px] font-black uppercase text-[#c45a00]">{pbOptionLabel(t, expense.category)}</span><h3 className="mt-2 font-black text-kharcha-navy">{expense.title}</h3><p className="text-xs font-bold text-gray-500">{expense.date}{expense.subcategory ? ` · ${pbOptionLabel(t, expense.subcategory)}` : ''} · {expense.paymentMethod ? pbOptionLabel(t, expense.paymentMethod) : '—'}</p><p className={`mt-1 text-xs font-black ${expense.status === 'Paid' ? 'text-[#16834b]' : 'text-[#c45a00]'}`}>{pbOptionLabel(t, expense.status)}</p></div><b className="text-lg text-[#c45a00]">{money(expense.amount)}</b></div><div className="mt-3 flex gap-2"><Button size="sm" variant="outline" onClick={() => onEdit(expense)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Pencil size={13} className="mr-1" />{t('personalBudgetEdit')}</Button><Button size="sm" variant="outline" onClick={() => onDelete(expense.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black text-red-600"><Trash2 size={13} className="mr-1" />{t('personalBudgetDelete')}</Button></div></Card>)}</div>}<CategoryBudgetPanel t={t} categories={categories} budgets={budgets} actualExpenses={actualExpenses} selectedMonth={selectedMonth} onSetBudget={onSetBudget} /></section>; }

function CategoryBudgetPanel({ t, categories, budgets, actualExpenses, onSetBudget }: any) { return <Card className="rounded-2xl border border-[#d1e5d7] bg-white p-5 shadow-sm"><h3 className="font-black text-kharcha-navy">{t('personalBudgetCategoryBudget')}</h3><p className="mt-1 text-xs font-bold text-gray-500">{t('pbCategoryBudgetHelp' as any)}</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{categories.map((category: ExpenseCategoryDefinition) => { const budget = budgets.find((item: Budget) => item.category === category.name); const actual = actualExpenses.filter((item: ExpenseTransaction) => item.status === 'Paid' && item.includeInBudget !== false && item.category === category.name).reduce((sum: number, item: ExpenseTransaction) => sum + item.amount, 0); const percent = budget?.plannedAmount ? Math.round(actual / budget.plannedAmount * 100) : 0; const status = !budget ? null : percent > 100 ? t('personalBudgetOverBudget') : percent >= 80 ? t('personalBudgetNearLimit') : t('personalBudgetUnderBudget'); return <div key={category.id} className="rounded-xl border border-[#d1e5d7] bg-gray-50 p-3"><div className="flex items-center justify-between"><span className="font-black">{category.icon} {pbOptionLabel(t, category.name)}</span>{status && <span className={`text-[10px] font-black ${percent > 100 ? 'text-red-600' : percent >= 80 ? 'text-[#c45a00]' : 'text-[#16834b]'}`}>{status}</span>}</div><div className="mt-2 flex items-center gap-2"><Input type="number" min="0" placeholder={t('personalBudgetBudgetAmount')} defaultValue={budget?.plannedAmount || ''} onBlur={e => onSetBudget(category.name, e.target.value)} className="min-h-10 border border-[#d1e5d7] bg-white font-bold" /><span className="shrink-0 text-xs font-black text-gray-600">{t('pbActual' as any)} {money(actual)}</span></div>{budget && <p className="mt-1 text-xs font-bold text-gray-600">{money(actual)} / {money(budget.plannedAmount)} · {percent}% {t('pbUsed' as any)}{percent <= 100 ? ` · ${money(budget.plannedAmount - actual)} ${t('pbRemaining' as any).toLowerCase()}` : ` · ${money(actual - budget.plannedAmount)} ${t('pbOver' as any)}`}</p>}</div>; })}</div></Card>; }

function RecurringScreen({ t, rules, occurrences, selectedMonth, commitment, recurringPaid, recurringPending, recurringSkipped, upcoming, onAdd, onEdit, onToggle, onPause, onArchive, onDeleteFuture, onSkipRange, onBulkPaid, onStatus, onMarkPaid, onEditOccurrence }: any) {
  const todayItems = occurrences.filter((item: ExpenseTransaction) => item.date === today());
  const skippedItems = occurrences.filter((item: ExpenseTransaction) => item.status === 'Skipped');
  const activeRules = rules.filter((rule: RecurringExpenseRule) => rule.status === 'Active');
  const pausedRules = rules.filter((rule: RecurringExpenseRule) => rule.status === 'Paused');
  const archivedRules = rules.filter((rule: RecurringExpenseRule) => rule.status === 'Archived');
  const statusView = (item: ExpenseTransaction) => item.status === 'Paid' ? { label: `✓ ${t('personalBudgetPaid')}`, className: 'bg-[#dff1e5] text-[#16834b]' } : item.status === 'Skipped' ? { label: `— ${t('personalBudgetSkipped')}`, className: 'bg-gray-200 text-gray-700' } : item.status === 'Cancelled' ? { label: `× ${t('personalBudgetCancelled')}`, className: 'bg-red-100 text-red-700' } : { label: `• ${t('personalBudgetPending')}`, className: 'bg-[#fff3e3] text-[#c45a00]' };
  const occurrenceList = (items: ExpenseTransaction[], empty: string) => items.length ? <div className="mt-3 space-y-2">{items.map((item: ExpenseTransaction) => { const status = statusView(item); return <div key={item.id} className="rounded-xl border border-[#d1e5d7] bg-gray-50 p-3"><div className="flex items-start justify-between gap-2"><div><p className="font-black text-kharcha-navy">{item.title}</p><p className="text-xs font-bold text-gray-500">{item.date} · {money(item.amount)} · {pbOptionLabel(t, item.category)}</p></div><span className={`rounded-full px-2 py-1 text-[10px] font-black ${status.className}`}>{status.label}</span></div><div className="mt-2 flex flex-wrap gap-2">{item.status !== 'Paid' && <Button size="sm" variant="outline" onClick={() => onMarkPaid(item.id)} className="min-h-8 rounded-xl border border-[#d1e5d7] font-black"><Check size={12} className="mr-1" />{t('personalBudgetMarkPaid')}</Button>}{item.status !== 'Planned' && <Button size="sm" variant="outline" onClick={() => onStatus(item.id, 'Planned')} className="min-h-8 rounded-xl border border-[#d1e5d7] font-black">{t('personalBudgetMarkPending')}</Button>}{item.status !== 'Skipped' && <Button size="sm" variant="outline" onClick={() => onStatus(item.id, 'Skipped')} className="min-h-8 rounded-xl border border-[#d1e5d7] font-black"><SkipForward size={12} className="mr-1" />{t('personalBudgetMarkSkipped')}</Button>}{item.status !== 'Cancelled' && <Button size="sm" variant="outline" onClick={() => onStatus(item.id, 'Cancelled')} className="min-h-8 rounded-xl border border-[#d1e5d7] font-black text-red-600"><Ban size={12} className="mr-1" />{t('personalBudgetMarkCancelled')}</Button>}<Button size="sm" variant="outline" onClick={() => onEditOccurrence(item)} className="min-h-8 rounded-xl border border-[#d1e5d7] font-black"><Pencil size={12} className="mr-1" />{t('personalBudgetEdit')}</Button></div></div>; })}</div> : <p className="mt-3 text-sm font-bold text-gray-500">{empty}</p>;
  const ruleCard = (rule: RecurringExpenseRule) => { const next = calculateNextOccurrenceDate(rule, today()); const ruleClass = rule.status === 'Active' ? 'bg-[#dff1e5] text-[#16834b]' : rule.status === 'Paused' ? 'bg-[#fff3e3] text-[#c45a00]' : 'bg-gray-100 text-gray-700'; return <Card key={rule.id} className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><span className={`rounded-full border border-[#d1e5d7] px-2 py-1 text-[10px] font-black uppercase ${ruleClass}`}>{rule.status === 'Active' ? `✓ ${t('personalBudgetActive')}` : rule.status === 'Paused' ? `|| ${t('personalBudgetPaused')}` : pbOptionLabel(t, rule.status)}</span><h3 className="mt-2 text-lg font-black text-kharcha-navy">{rule.title}</h3><p className="text-xs font-bold text-gray-600">{money(rule.amount)} · {pbOptionLabel(t, rule.frequency)}{rule.intervalCount && rule.frequency === 'Custom' ? ` × ${rule.intervalCount}` : ''} · {pbOptionLabel(t, rule.category)}</p><p className="mt-1 text-xs font-bold text-gray-500">{t('personalBudgetNextOccurrence')}: {next ?? '—'} · {rule.includeInBudget === false ? t('personalBudgetExcludeFromBudget') : t('personalBudgetIncludeInBudget')}</p></div><Repeat2 className="text-[#16834b]" size={22} /></div><div className="mt-4 flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => onEdit(rule)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Pencil size={13} className="mr-1" />{t('personalBudgetEdit')}</Button>{rule.status === 'Active' ? <Button size="sm" variant="outline" onClick={() => onPause(rule.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Pause size={13} className="mr-1" />{t('personalBudgetPause')}</Button> : rule.status === 'Paused' ? <Button size="sm" variant="outline" onClick={() => onToggle(rule.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Play size={13} className="mr-1" />{t('personalBudgetResume')}</Button> : null}<Button size="sm" variant="outline" onClick={() => onSkipRange(rule.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><SkipForward size={13} className="mr-1" />{t('personalBudgetMarkSkipped')}</Button>{rule.status !== 'Archived' && <Button size="sm" variant="outline" onClick={() => onArchive(rule.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Archive size={13} className="mr-1" />{t('personalBudgetArchiveRule')}</Button>}{rule.status === 'Active' && <Button size="sm" variant="outline" onClick={() => onDeleteFuture(rule.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black text-red-600"><Trash2 size={13} className="mr-1" />{t('personalBudgetDeleteFuture')}</Button>}</div></Card>; };
  return <section className="space-y-4"><div className="android-section-header flex flex-col gap-3 rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-xl font-black text-kharcha-navy">{t('personalBudgetRecurring')}</h2><p className="text-xs font-bold text-gray-600">{t('personalBudgetRecurringDescription')}</p></div><div className="android-action-row flex flex-wrap gap-2"><Button onClick={onBulkPaid} variant="outline" className="min-h-11 rounded-xl border border-[#d1e5d7] bg-white font-black"><ListChecks size={15} className="mr-1" />{t('personalBudgetMarkPaid')}</Button><Button onClick={onAdd} className="min-h-11 rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white"><Plus size={15} className="mr-1" />{t('personalBudgetAddRecurring')}</Button></div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><MetricPill label={t('personalBudgetMonthlyCommitment')} value={money(commitment.commitment)} tone="green" /><MetricPill label={t('personalBudgetRecurringPaid')} value={money(recurringPaid)} tone="blue" /><MetricPill label={t('personalBudgetRecurringPending')} value={money(recurringPending)} tone="orange" /><MetricPill label={t('personalBudgetRecurringSkipped')} value={money(recurringSkipped)} tone="gray" /></div>{todayItems.length > 0 && <Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><h3 className="flex items-center gap-2 font-black text-kharcha-navy"><CalendarClock size={18} className="text-[#16834b]" />{t('personalBudgetToday')}</h3>{occurrenceList(todayItems, t('personalBudgetNoOccurrences'))}</Card>}<Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><h3 className="flex items-center gap-2 font-black text-kharcha-navy"><CalendarDays size={18} className="text-[#c45a00]" />{t('personalBudgetUpcoming')}</h3>{occurrenceList(upcoming, t('personalBudgetUpcomingEmpty'))}</Card><Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><h3 className="font-black text-kharcha-navy">{t('personalBudgetOccurrences')} · {selectedMonth}</h3>{occurrenceList(occurrences.filter((item: ExpenseTransaction) => item.date !== today() && item.status !== 'Skipped'), t('personalBudgetNoOccurrences'))}</Card>{skippedItems.length > 0 && <Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><h3 className="font-black text-kharcha-navy">{t('personalBudgetSkipped')}</h3>{occurrenceList(skippedItems, t('personalBudgetNoSkipped'))}</Card>}<section><div className="mb-2 flex items-center justify-between"><h3 className="font-black text-kharcha-navy">{t('personalBudgetActiveRules')}</h3><span className="text-xs font-black text-gray-500">{activeRules.length}</span></div><div className="grid gap-3 md:grid-cols-2">{activeRules.length ? activeRules.map(ruleCard) : <EmptyCard title={t('personalBudgetNoRecurringRules')} text={t('personalBudgetRecurringDescription')} action={t('personalBudgetAddRecurring')} onClick={onAdd} />}</div></section>{pausedRules.length > 0 && <section><div className="mb-2 flex items-center justify-between"><h3 className="font-black text-kharcha-navy">{t('personalBudgetPaused')}</h3><span className="text-xs font-black text-gray-500">{pausedRules.length}</span></div><div className="grid gap-3 md:grid-cols-2">{pausedRules.map(ruleCard)}</div></section>}{archivedRules.length > 0 && <section><div className="mb-2 flex items-center justify-between"><h3 className="font-black text-kharcha-navy">{t('personalBudgetArchivedRules')}</h3><span className="text-xs font-black text-gray-500">{archivedRules.length}</span></div><div className="grid gap-3 md:grid-cols-2">{archivedRules.map(ruleCard)}</div></section>}</section>;
}

function RecurringModal({ t, form, setForm, categories, members, error, editing, onClose, onSave }: any) { const selected = categories.find((category: ExpenseCategoryDefinition) => category.name === form.category); return <ModalShell title={editing ? `${t('personalBudgetEdit')} ${t('personalBudgetRecurring')}` : t('personalBudgetAddRecurring')} onClose={onClose}><div className="mt-4 space-y-3"><Field label={t('personalBudgetRuleName')}><Input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Milk, Rent, Electricity" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetCategory')}><SelectField value={form.category} onChange={category => setForm({ ...form, category, subcategory: categories.find((item: ExpenseCategoryDefinition) => item.name === category)?.subcategories?.[0] ?? '' })} options={categories.map((category: ExpenseCategoryDefinition) => String(category.name))} /></Field><Field label={t('personalBudgetSubcategory')}><SelectField value={form.subcategory} onChange={subcategory => setForm({ ...form, subcategory })} options={selected?.subcategories?.length ? selected.subcategories : ['Other']} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetAmount')}><Input type="number" min="0.01" inputMode="decimal" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="8000" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('pbAmountType' as any)}><SelectField value={form.amountType} onChange={amountType => setForm({ ...form, amountType })} options={['Fixed', 'Variable']} /></Field></div><Field label={t('personalBudgetFrequency')}><SelectField value={form.frequency} onChange={frequency => setForm({ ...form, frequency })} options={recurringFrequencies} /></Field>{form.frequency === 'Weekly' && <div className="grid gap-3 sm:grid-cols-2"><Field label={t('auditWeekday' as any)}><SelectField value={form.dayOfWeek} onChange={dayOfWeek => setForm({ ...form, dayOfWeek })} options={['0 · Sunday', '1 · Monday', '2 · Tuesday', '3 · Wednesday', '4 · Thursday', '5 · Friday', '6 · Saturday']} /></Field><Field label={t('auditEveryNWeeks' as any)}><Input type="number" min="1" value={form.intervalCount} onChange={e => setForm({ ...form, intervalCount: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div>}{form.frequency === 'Monthly' && <Field label={t('auditDayOfMonth' as any)}><Input type="number" min="1" max="31" value={form.dayOfMonth} onChange={e => setForm({ ...form, dayOfMonth: e.target.value })} placeholder="1" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field>}{form.frequency === 'Yearly' && <div className="grid gap-3 sm:grid-cols-2"><Field label={t('pbMonths' as any)}><Input type="number" min="1" max="12" value={form.monthOfYear} onChange={e => setForm({ ...form, monthOfYear: e.target.value })} placeholder="9" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('pbDay' as any)}><Input type="number" min="1" max="31" value={form.dayOfMonth} onChange={e => setForm({ ...form, dayOfMonth: e.target.value })} placeholder="10" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div>}{form.frequency === 'Quarterly' && <Field label={t('auditQuarterStarts' as any)}><p className="mt-1 rounded-xl border border-[#d1e5d7] bg-gray-50 p-3 text-xs font-bold text-gray-600">{t('auditEveryThreeMonths' as any)}</p></Field>}{form.frequency === 'Custom' && <div className="rounded-xl border border-[#d1e5d7] bg-[#fffaf3] p-3"><p className="text-xs font-black text-kharcha-navy">{t('auditAdvancedRecurrence' as any)}</p><p className="mt-1 text-xs font-bold text-gray-600">{t('auditEveryNPeriods' as any)}</p><div className="mt-2 grid grid-cols-2 gap-2"><Input type="number" min="1" value={form.intervalCount} onChange={e => setForm({ ...form, intervalCount: e.target.value })} className="min-h-11 border border-[#d1e5d7] bg-white" /><SelectField value={form.customUnit} onChange={customUnit => setForm({ ...form, customUnit })} options={['days', 'weeks', 'months', 'years']} /></div></div>}<div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetStartDate')}><Input type="date" value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetEndDate')}><Input type="date" value={form.endDate} onChange={e => setForm({ ...form, endDate: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetPaymentMethod')}><SelectField value={form.paymentMethod} onChange={paymentMethod => setForm({ ...form, paymentMethod })} options={paymentMethods} /></Field><Field label={t('personalBudgetPerson')}><SelectField value={form.personId} onChange={personId => setForm({ ...form, personId })} options={[...members.map((member: any) => member.name), 'Other']} /></Field></div><Field label={t('personalBudgetNote')}><Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder={t('auditOptionalNote' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><label className="flex min-h-11 items-center gap-2 rounded-xl border border-[#d1e5d7] bg-[#f2fbf3] px-3 text-sm font-black"><Checkbox checked={form.active} onCheckedChange={checked => setForm({ ...form, active: checked === true })} />{t('auditActive' as any)}</label><label className="flex min-h-11 items-center gap-2 rounded-xl border border-[#d1e5d7] bg-[#f2fbf3] px-3 text-sm font-black"><Checkbox checked={form.includeInBudget} onCheckedChange={checked => setForm({ ...form, includeInBudget: checked === true })} />{t('personalBudgetRecurringBudgetQuestion')}</label><ErrorText error={error} /><Button onClick={onSave} className="min-h-12 w-full rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white">{t('personalBudgetSave')}</Button></div></ModalShell>; }

function EmptyCard({ title, text, action, onClick }: { title: string; text: string; action: string; onClick: () => void }) { return <Card className="rounded-2xl border border-[#d1e5d7] bg-white p-6 text-center shadow-sm"><h3 className="font-black text-kharcha-navy">{title}</h3><p className="mt-1 text-sm font-bold text-gray-500">{text}</p><Button onClick={onClick} className="mt-4 min-h-11 rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white">{action}</Button></Card>; }

function ModalShell({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/50 p-3 sm:items-center"><Card className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-3xl border border-[#d1e5d7] bg-white p-5 shadow-[5px_5px_0px_0px_rgba(0,0,0,1)]"><div className="flex items-center justify-between"><h2 className="text-xl font-black text-kharcha-navy">{title}</h2><Button variant="outline" size="sm" onClick={onClose} className="h-9 w-9 rounded-full border border-[#d1e5d7] p-0"><X size={16} /></Button></div>{children}</Card></div>; }

function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block text-xs font-black text-kharcha-navy">{label}{children}</label>; }
function pbOptionLabel(t: (key: any, variables?: any) => string, value: string): string {
  const keys: Record<string, string> = {
    Self: 'pbSelf', Other: 'pbOther', Housing: 'pbHousing', Rent: 'pbRent', Maintenance: 'pbMaintenance', Food: 'pbFood', Groceries: 'pbGroceriesValue', Milk: 'auditMilk', Restaurant: 'pbRestaurant', 'Food Delivery': 'pbFoodDelivery', Transport: 'pbTransport', Fuel: 'pbFuel', Taxi: 'pbTaxi', Bus: 'pbBus', Train: 'pbTrain', Parking: 'pbParking', Toll: 'pbToll', Utilities: 'pbUtilities', Electricity: 'pbElectricity', Water: 'pbWater', Gas: 'pbGas', Internet: 'pbInternet', Health: 'pbHealth', Doctor: 'pbDoctor', Medicine: 'pbMedicine', Hospital: 'pbHospital', Education: 'pbEducation', School: 'pbSchool', Tuition: 'pbTuition', Books: 'pbBooks', Family: 'pbFamily', Children: 'pbChildren', Parents: 'pbParents', Household: 'pbHousehold', Lifestyle: 'pbLifestyle', Shopping: 'pbShopping', Entertainment: 'pbEntertainment', Gym: 'pbGym', Subscription: 'pbSubscription', Subscriptions: 'pbSubscriptions', Financial: 'pbFinancial', EMI: 'pbEmi', Insurance: 'pbInsurance', Investment: 'pbInvestment', Miscellaneous: 'pbMiscellaneous', Salary: 'pbSalary', Business: 'pbBusiness', Rental: 'pbRental', Freelance: 'pbFreelance', Commission: 'pbCommission', Interest: 'pbInterest', Dividend: 'pbDividend', Pension: 'pbPension', Bonus: 'pbBonus', Daily: 'pbDaily', Weekly: 'pbWeekly', Monthly: 'pbMonthly', Quarterly: 'pbQuarterly', Yearly: 'pbYearly', Custom: 'pbCustom', OneTime: 'pbOneTime', 'One-time': 'pbOneTime', Irregular: 'pbIrregular', Cash: 'pbCash', UPI: 'pbUpi', Bank: 'pbBank', 'Credit Card': 'pbCreditCard', 'Debit Card': 'pbDebitCard', Wallet: 'pbWallet', Fixed: 'pbFixed', Variable: 'pbVariable', Planned: 'pbPlanned', Expected: 'pbExpectedStatus', Received: 'pbReceived', Partial: 'pbPartial', Paid: 'pbPaidStatus', Skipped: 'pbSkippedStatus', Cancelled: 'pbCancelledStatus', Active: 'pbActive', Archived: 'pbArchived', Paused: 'pbPaused', Low: 'pbLow', Medium: 'pbMedium', High: 'pbHigh', '0 · Sunday': 'pbSunday', '1 · Monday': 'pbMonday', '2 · Tuesday': 'pbTuesday', '3 · Wednesday': 'pbWednesday', '4 · Thursday': 'pbThursday', '5 · Friday': 'pbFriday', '6 · Saturday': 'pbSaturday', days: 'pbDays', weeks: 'pbWeeks', months: 'pbMonths', years: 'pbYears'
  };
  const key = keys[value];
  return key ? t(key) : value;
}
function guidanceLabel(t: (key: any, variables?: any) => string, item: { level: string; title: string; message: string }) {
  const levelKeys: Record<string, string> = { Information: 'auditInformation', Attention: 'auditAttention', Warning: 'auditWarning' };
  const titleKeys: Record<string, string> = { 'Budget needs attention': 'auditBudgetNeedsAttention', 'Low remaining budget': 'auditLowRemainingBudget', 'Within planned spending': 'auditWithinPlannedSpending', 'High daily spending': 'auditHighDailySpending', 'Goal allocation guidance': 'auditGoalAllocationGuidance', 'Goals are on track': 'auditGoalsOnTrack' };
  const amount = item.message.match(/₹[\d,]+/)?.[0] ?? '';
  let title = titleKeys[item.title] ? t(titleKeys[item.title]) : item.title;
  if (item.title.endsWith(' spending')) title = `${pbOptionLabel(t, item.title.slice(0, -' spending'.length))} ${t('auditSpendingSuffix' as any)}`;
  let message = item.message;
  if (item.message.includes('above expected income')) message = t('auditBudgetAboveIncome' as any, { amount });
  else if (item.message.endsWith('is remaining for this month.')) message = t('auditAmountRemainingThisMonth' as any, { amount });
  else if (item.message.includes('remains after commitments')) message = t('auditAmountRemainsAfterCommitments' as any, { amount });
  else if (item.message.includes('above the suggested daily average')) message = t('auditTodaySpendingAboveAverage' as any, { amount });
  else if (item.message.includes('more needs to be allocated')) message = t('auditMoreNeedsAllocation' as any, { amount });
  else if (item.message.includes('allocated') && item.message.includes('goal requirements')) message = t('auditAllocatedTowardGoals' as any, { amount });
  else if (item.message.endsWith('is above the planned amount.')) message = t('auditAbovePlannedAmount' as any, { amount });
  return { level: levelKeys[item.level] ? t(levelKeys[item.level]) : item.level, title, message };
}
function SelectField({ value, onChange, options }: { value: string; onChange: (value: string) => void; options: string[] }) { const { t } = useLanguage(); return <select value={value} onChange={e => onChange(e.target.value)} className="mt-1 min-h-11 w-full rounded-xl border border-[#d1e5d7] bg-white px-3 text-sm font-bold text-black">{options.map(option => <option key={option} value={option}>{pbOptionLabel(t, option)}</option>)}</select>; }
function ErrorText({ error }: { error: string }) { return error ? <p className="rounded-xl border-2 border-red-600 bg-red-50 p-2 text-xs font-black text-red-600">{error}</p> : null; }

function IncomeSourceModal({ t, form, setForm, members, editing, error, onClose, onSave }: any) { return <ModalShell title={editing ? `${t('personalBudgetEdit')} ${t('personalBudgetIncomeSources')}` : t('personalBudgetAddIncomeSource')} onClose={onClose}><div className="mt-4 space-y-3"><Field label={t('personalBudgetIncomeName')}><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder={t('pbSalary' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetCategory')}><SelectField value={form.category} onChange={category => setForm({ ...form, category })} options={incomeCategories} /></Field><Field label={t('personalBudgetFrequency')}><SelectField value={form.frequency} onChange={frequency => setForm({ ...form, frequency })} options={frequencies} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetAmount')}><Input type="number" min="0" inputMode="decimal" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder={t('pbIncomeAmountPlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('pbAmountType' as any)}><SelectField value={form.amountType} onChange={amountType => setForm({ ...form, amountType })} options={['Fixed', 'Variable']} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetExpectedDate')}><Input type="date" value={form.expectedDate} onChange={e => setForm({ ...form, expectedDate: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetPerson')}><SelectField value={form.personId} onChange={personId => setForm({ ...form, personId })} options={[...members.map((member: any) => member.name), 'Other']} /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetStartDate')}><Input type="date" value={form.startDate} onChange={e => setForm({ ...form, startDate: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetEndDate')}><Input type="date" value={form.endDate} onChange={e => setForm({ ...form, endDate: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div><label className="flex min-h-11 items-center gap-2 rounded-xl border border-[#d1e5d7] bg-[#f2fbf3] px-3 text-sm font-black"><Checkbox checked={form.includeInBudget} onCheckedChange={checked => setForm({ ...form, includeInBudget: checked === true })} />{t('personalBudgetIncludeInBudget')}</label><ErrorText error={error} /><Button onClick={onSave} className="min-h-12 w-full rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white shadow-sm">{t('personalBudgetSave')}</Button></div></ModalShell>; }

function IncomeTransactionModal({ t, form, setForm, sources, error, onClose, onSave }: any) { return <ModalShell title={t('personalBudgetAddIncomeTransaction')} onClose={onClose}><div className="mt-4 space-y-3"><Field label={t('personalBudgetIncomeName')}><Input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder={t('pbIncomeTransactionExamples' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetActualAmount')}><Input type="number" min="0.01" inputMode="decimal" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder={t('pbTransactionAmountPlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetTransactionDate')}><Input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('pbSourceOptional' as any)}><SelectField value={form.sourceId} onChange={sourceId => setForm({ ...form, sourceId })} options={['', ...sources.map((source: IncomeSource) => source.id)]} /></Field><Field label={t('pbStatus' as any)}><SelectField value={form.status} onChange={status => setForm({ ...form, status })} options={['Received', 'Partial', 'Expected']} /></Field></div><ErrorText error={error} /><Button onClick={onSave} className="min-h-12 w-full rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white">{t('personalBudgetSave')}</Button></div></ModalShell>; }

function ExpenseModal({ t, form, setForm, categories, error, editing, onClose, onSave }: any) {
  const selected = categories.find((category: ExpenseCategoryDefinition) => category.name === form.category);
  const entryOptions: ExpenseType[] = ['Daily', 'Weekly', 'OneTime'];
  const entryLabel = (option: ExpenseType) => option === 'OneTime' ? t('auditOtherOneTime' as any) : option === 'Weekly' ? t('auditWeeklyExpense' as any) : t('auditDailyExpense' as any);
  const title = editing ? `${t('personalBudgetEdit')} ${t('personalBudgetExpenses')}` : `${t('personalBudgetAddExpense')} · ${entryLabel(form.expenseType)}`;
  return <ModalShell title={title} onClose={onClose}>
    <div className="mt-4 space-y-3">
      {!editing && !form.recurringRuleId && <div className="grid grid-cols-3 gap-2">{entryOptions.map(option => <button key={option} type="button" onClick={() => setForm({ ...form, expenseType: option, weekLabel: option === 'Weekly' ? form.weekLabel : '' })} className={`min-h-10 rounded-xl border border-[#d1e5d7] px-2 text-xs font-black ${form.expenseType === option ? 'bg-[#16834b] text-white' : 'bg-white text-black'}`}>{entryLabel(option)}</button>)}</div>}
      <Field label={form.expenseType === 'Weekly' ? t('auditWeeklyAmount' as any) : t('personalBudgetAmount')}><Input type="number" min="0.01" inputMode="decimal" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder={t('pbExpenseAmountPlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field>
      {form.expenseType === 'Weekly' && <Field label={t('auditWeekOf' as any)}><Input type="date" value={form.weekLabel || form.date} onChange={e => setForm({ ...form, weekLabel: e.target.value, date: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field>}
      <div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetCategory')}><SelectField value={form.category} onChange={category => setForm({ ...form, category, subcategory: categories.find((item: ExpenseCategoryDefinition) => item.name === category)?.subcategories?.[0] ?? '' })} options={categories.map((category: ExpenseCategoryDefinition) => String(category.name))} /></Field><Field label={t('personalBudgetSubcategory')}><SelectField value={form.subcategory} onChange={subcategory => setForm({ ...form, subcategory })} options={selected?.subcategories?.length ? selected.subcategories : ['Other']} /></Field></div>
      <div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetTransactionDate')}><Input type="date" value={form.date} onChange={e => setForm({ ...form, date: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetPaymentMethod')}><SelectField value={form.paymentMethod} onChange={paymentMethod => setForm({ ...form, paymentMethod })} options={paymentMethods} /></Field></div>
      <Field label={t('personalBudgetPerson')}><SelectField value={form.personId} onChange={personId => setForm({ ...form, personId })} options={['Self', 'Other']} /></Field>
      <Field label={t('personalBudgetNote')}><Input value={form.note} onChange={e => setForm({ ...form, note: e.target.value })} placeholder={t('auditOptionalNote' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field>
      <label className="flex min-h-11 items-center gap-2 rounded-xl border border-[#d1e5d7] bg-[#fffaf3] px-3 text-sm font-black"><Checkbox checked={form.status === 'Paid'} onCheckedChange={checked => setForm({ ...form, status: checked === true ? 'Paid' : 'Planned' })} />{t('auditMarkAsPaid' as any)}</label>
      <label className="flex min-h-11 items-center gap-2 rounded-xl border border-[#d1e5d7] bg-[#f2fbf3] px-3 text-sm font-black"><Checkbox checked={form.includeInBudget} onCheckedChange={checked => setForm({ ...form, includeInBudget: checked === true })} />{t('personalBudgetIncludeInBudget')}</label>
      <ErrorText error={error} /><Button onClick={onSave} className="min-h-12 w-full rounded-xl border border-[#d1e5d7] bg-[#e87817] font-black text-white">{t('personalBudgetSave')}</Button>
    </div>
  </ModalShell>;
}

function CategoryModal({ t, name, icon, setName, setIcon, error, categories, onClose, onSave }: any) { return <ModalShell title={t('personalBudgetManageCategories')} onClose={onClose}><div className="mt-4 space-y-3"><div className="rounded-xl border border-[#d1e5d7] bg-gray-50 p-3 text-xs font-bold text-gray-600">{categories.map((category: ExpenseCategoryDefinition) => category.name).join(' · ')}</div><h3 className="font-black text-kharcha-navy">{t('personalBudgetAddCustomCategory')}</h3><Field label={t('personalBudgetCategoryName')}><Input value={name} onChange={e => setName(e.target.value)} placeholder={t('pbCategoryPlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetIcon')}><Input value={icon} onChange={e => setIcon(e.target.value)} placeholder="🐾" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><ErrorText error={error} /><Button onClick={onSave} className="min-h-12 w-full rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white">{t('personalBudgetAdd')}</Button></div></ModalShell>; }

function HistoryModal({ t, source, transactions, onClose }: any) { return <ModalShell title={`${source.name} · ${t('personalBudgetIncomeHistory')}`} onClose={onClose}><div className="mt-4 space-y-2">{transactions.length ? transactions.map((item: IncomeTransaction) => <div key={item.id} className="flex justify-between border-b border-gray-100 py-2 text-sm font-bold"><span>{item.date} · {pbOptionLabel(t, item.status)}</span><b className="text-[#16834b]">{money(item.amount)}</b></div>) : <p className="text-sm font-bold text-gray-500">{t('personalBudgetHistoryEmpty')}</p>}</div></ModalShell>; }

function CalendarScreen({ t, monthSelector, selectedMonth, expenses, income, occurrences }: any) { const [year, month] = selectedMonth.split('-').map(Number); const daysInMonth = new Date(year, month, 0).getDate(); const firstWeekday = new Date(year, month - 1, 1).getDay(); const days = Array.from({ length: firstWeekday + daysInMonth }, (_, index) => index < firstWeekday ? null : index - firstWeekday + 1); return <section className="space-y-4">{monthSelector}<Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><div className="flex items-center gap-2"><CalendarDays size={19} className="text-[#16834b]" /><div><h2 className="text-xl font-black text-kharcha-navy">{t('personalBudgetCalendar')}</h2><p className="text-xs font-bold text-gray-500">{t('personalBudgetRecurringDescription')}</p></div></div><div className="mt-4 grid grid-cols-7 gap-1 text-center text-[10px] font-black uppercase text-gray-500">{[t('pbSunday' as any), t('pbMonday' as any), t('pbTuesday' as any), t('pbWednesday' as any), t('pbThursday' as any), t('pbFriday' as any), t('pbSaturday' as any)].map(day => <span key={day} className="py-2">{day}</span>)}{days.map((day, index) => { if (!day) return <span key={`empty_${index}`} className="min-h-20 rounded-xl bg-gray-50" />; const date = `${selectedMonth}-${String(day).padStart(2, '0')}`; const dayExpenses = expenses.filter((item: ExpenseTransaction) => item.date === date); const dayIncome = income.filter((item: IncomeTransaction) => item.date === date); const dayOccurrences = occurrences.filter((item: ExpenseTransaction) => item.date === date); return <div key={date} className={`min-h-20 rounded-xl border-2 p-1 text-left ${dayOccurrences.some((item: ExpenseTransaction) => item.status === 'Planned') ? 'border-[#e87817] bg-[#fffaf3]' : 'border-[#d1e5d7] bg-white'}`}><p className="text-xs font-black text-kharcha-navy">{day}</p>{dayIncome.slice(0, 1).map((item: IncomeTransaction) => <p key={item.id} className="mt-1 truncate rounded bg-[#dff1e5] px-1 text-[9px] font-black text-[#16834b]">+{money(item.amount)}</p>)}{dayExpenses.slice(0, 2).map((item: ExpenseTransaction) => <p key={item.id} className={`mt-1 truncate rounded px-1 text-[9px] font-black ${item.status === 'Paid' ? 'bg-gray-100 text-gray-700' : 'bg-[#ffe8cf] text-[#c45a00]'}`}>−{money(item.amount)}{item.recurringRuleId ? ' ↻' : ''}</p>)}</div>; })}</div></Card><Card className="rounded-2xl border border-[#d1e5d7] bg-white p-4 shadow-sm"><h3 className="font-black text-kharcha-navy">{t('personalBudgetOccurrenceDetails')}</h3><div className="mt-3 space-y-2">{occurrences.length ? occurrences.map((item: ExpenseTransaction) => <div key={item.id} className="flex items-center justify-between rounded-xl border border-[#d1e5d7] bg-gray-50 p-3 text-sm"><span><b>{item.title}</b><span className="ml-2 text-xs font-bold text-gray-500">{item.date}</span></span><span className="font-black text-[#c45a00]">{money(item.amount)} · {pbOptionLabel(t, item.status)}</span></div>) : <p className="text-sm font-bold text-gray-500">{t('personalBudgetNoOccurrences')}</p>}</div></Card></section>; }

function PlaceholderScreen({ t, title, icon: Icon }: { t: (key: any) => string; title: string; icon: typeof Wallet }) { return <section className="mx-auto max-w-2xl"><Card className="rounded-3xl border border-[#d1e5d7] bg-white p-8 text-center shadow-md"><span className="mx-auto grid h-16 w-16 place-items-center rounded-2xl border border-[#d1e5d7] bg-[#ffe8cf] text-[#c45a00]"><Icon size={30} /></span><h2 className="mt-4 text-2xl font-black text-kharcha-navy">{title}</h2><p className="mt-2 text-sm font-bold text-gray-600">{t('personalBudgetComingSoon')}</p><Button disabled className="mt-5 min-h-11 rounded-xl border border-[#d1e5d7] bg-gray-200 font-black text-gray-500">{t('personalBudgetNoData')}</Button></Card></section>; }

function StepFivePanel({ t, summary, guidance, goals, onGoal, onEditGoal, onAddContribution, onDeleteGoal }: any) {
  return <div className="space-y-4"><section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><MetricPill label={t('personalBudgetSafeSpendingAmount')} value={money(summary.safeSpendingAmount)} tone="green" /><MetricPill label={t('personalBudgetSuggestedDailyLimit')} value={`${money(summary.suggestedDailyLimit)}/day`} tone="blue" /><MetricPill label={t('personalBudgetTodaysSpending')} value={money(summary.todaySpending)} tone="orange" /><MetricPill label={t('personalBudgetGoalCommitments')} value={`${money(summary.goalCommitments)}/month`} tone="gray" /></section><Card className="rounded-2xl border border-[#d1e5d7] bg-[#fffaf3] p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><h3 className="font-black text-kharcha-navy">{t('personalBudgetSmartGuidance')}</h3><p className="mt-1 text-xs font-bold text-gray-600">{t('personalBudgetGuidanceOnly')}</p></div><AlertTriangle size={20} className="text-[#c45a00]" /></div><div className="mt-3 space-y-2">{guidance.map((item: any) => { const localized = guidanceLabel(t, item); return <div key={`${item.title}-${item.message}`} className={`rounded-xl border border-[#d1e5d7] p-3 text-sm font-bold ${item.level === 'Warning' ? 'bg-red-50 text-red-700' : item.level === 'Attention' ? 'bg-[#fff3e3] text-[#9a4a00]' : 'bg-[#dff1e5] text-[#166b3f]'}`}><span className="font-black">{localized.level}: </span>{localized.title} — {localized.message}</div>; })}</div></Card><section className="rounded-2xl border border-[#d1e5d7] bg-white p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><h3 className="font-black text-kharcha-navy">{t('personalBudgetGoalsTitle')}</h3><p className="mt-1 text-xs font-bold text-gray-600">{t('auditGoalGuidance' as any)}</p></div><Button onClick={onGoal} className="min-h-10 rounded-xl border border-[#d1e5d7] bg-[#e87817] font-black text-white"><Plus size={14} className="mr-1" />{t('personalBudgetAddGoal')}</Button></div>{goals.length ? <div className="mt-4 grid gap-3 md:grid-cols-2">{goals.filter((goal: Goal) => goal.status !== 'Paused').sort((a: Goal, b: Goal) => (a.priority === 'High' ? -1 : b.priority === 'High' ? 1 : 0)).map((goal: Goal) => { const progress = goalProgress(goal); return <Card key={goal.id} className="rounded-xl border border-[#d1e5d7] bg-[#f8fbf8] p-4"><div className="flex items-start justify-between gap-2"><div><p className="font-black text-kharcha-navy">{goal.title}</p><p className="text-xs font-bold text-gray-600">{money(goal.currentAmount)} / {money(goal.targetAmount)} · {progress.percentage}% · {pbOptionLabel(t, goal.priority ?? 'Medium')} {t('auditPrioritySuffix' as any)}</p></div><Target size={18} className="text-[#16834b]" /></div><div className="mt-3 h-2 overflow-hidden rounded-full border border-[#d1e5d7] bg-gray-100"><div className="h-full bg-[#16834b]" style={{ width: `${progress.percentage}%` }} /></div><p className="mt-2 text-xs font-bold text-gray-600">{t('auditGoalRemaining' as any)} {money(progress.remaining)} · {t('auditGoalRequired' as any)} {money(progress.requiredMonthly)}/month</p><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => onAddContribution(goal)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black">+ {t('personalBudgetAddToGoal')}</Button><Button size="sm" variant="outline" onClick={() => onEditGoal(goal)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black"><Pencil size={12} className="mr-1" />{t('personalBudgetEditGoal')}</Button><Button size="sm" variant="outline" onClick={() => onDeleteGoal(goal.id)} className="min-h-9 rounded-xl border border-[#d1e5d7] font-black text-red-600"><Trash2 size={12} className="mr-1" />{t('personalBudgetDelete')}</Button></div></Card>; })}</div> : <p className="mt-4 text-sm font-bold text-gray-500">{t('auditCreateGoalGuidance' as any)}</p>}</section></div>;
}

function GoalModal({ t, form, setForm, editing, error, onClose, onSave }: any) { return <ModalShell title={editing ? t('personalBudgetEditGoal') : t('personalBudgetAddGoal')} onClose={onClose}><div className="mt-4 space-y-3"><Field label={t('personalBudgetGoalName')}><Input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder={t('auditEmergencyFundPlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetTargetAmount')}><Input type="number" min="1" inputMode="decimal" value={form.targetAmount} onChange={e => setForm({ ...form, targetAmount: e.target.value })} placeholder="500000" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetCurrentSavedAmount')}><Input type="number" min="0" inputMode="decimal" value={form.currentAmount} onChange={e => setForm({ ...form, currentAmount: e.target.value })} placeholder="100000" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetTargetDate')}><Input type="date" value={form.targetDate} onChange={e => setForm({ ...form, targetDate: e.target.value })} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('auditCategory' as any)}><Input value={form.category} onChange={e => setForm({ ...form, category: e.target.value })} placeholder={t('auditEmergencyFundPlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field></div><div className="grid gap-3 sm:grid-cols-2"><Field label={t('personalBudgetMonthlyAllocation')}><Input type="number" min="0" inputMode="decimal" value={form.monthlyAllocation} onChange={e => setForm({ ...form, monthlyAllocation: e.target.value })} placeholder="10000" className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><Field label={t('personalBudgetPriority')}><SelectField value={form.priority} onChange={priority => setForm({ ...form, priority })} options={['Low', 'Medium', 'High']} /></Field></div><Field label={t('personalBudgetGoalNote')}><Input value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder={t('auditGoalNotePlaceholder' as any)} className="mt-1 min-h-11 border border-[#d1e5d7]" /></Field><label className="flex min-h-11 items-center gap-2 rounded-xl border border-[#d1e5d7] bg-[#f2fbf3] px-3 text-sm font-black"><Checkbox checked={form.active} onCheckedChange={checked => setForm({ ...form, active: checked === true })} />{t('personalBudgetActiveGoal')}</label><ErrorText error={error} /><Button onClick={onSave} className="min-h-12 w-full rounded-xl border border-[#d1e5d7] bg-[#16834b] font-black text-white">{t('personalBudgetSave')}</Button></div></ModalShell>; }
